use runtime_bridge::{Outcome,deliver,acme::{Server,AcmeTransport,Reply}};
use std::{sync::Arc,time::Duration};
#[tokio::test] async fn timeout_before_commit_then_retry(){let server=Arc::new(Server::default());let client=AcmeTransport::new(server.clone(),Reply::StallBeforeCommit);assert_eq!(deliver(&client,77,Duration::ZERO).await,Outcome::Retry(77));assert_eq!(server.effect_count(),0);drop(client);let retry=AcmeTransport::new(server.clone(),Reply::Normal);assert_eq!(deliver(&retry,77,Duration::from_secs(1)).await,Outcome::Delivered(77));assert_eq!(server.effect_count(),1);}
#[tokio::test] async fn reconnect_same_namespace_after_lost_reply(){let server=Arc::new(Server::default());let client=AcmeTransport::new(server.clone(),Reply::LoseAfterCommit);assert_eq!(deliver(&client,99,Duration::ZERO).await,Outcome::Retry(99));assert_eq!(server.effect_count(),1);drop(client);let retry=AcmeTransport::new(server.clone(),Reply::Normal);assert_eq!(deliver(&retry,99,Duration::from_secs(1)).await,Outcome::Delivered(99));assert_eq!(server.effect_count(),1);}
